function validate([houses, k]) {
  if (!Array.isArray(houses) || houses.length < 1 || houses.length > 100) return 'houses needs 1 to 100 values.';
  if (houses.some(h => !Number.isInteger(h) || h < 1 || h > 10000)) return 'Each house is an integer between 1 and 10^4.';
  if (new Set(houses).size !== houses.length) return 'House positions must be distinct.';
  if (!Number.isInteger(k) || k < 1 || k > houses.length) return 'k is between 1 and houses.length.';
  return null;
}

