function minDistance(houses, k) {
  houses.sort((a, b) => a - b);
  const n = houses.length;
  const cost = Array.from({ length: n }, () => new Array(n).fill(0));

  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      cost[i][j] = cost[i + 1][j - 1] + houses[j] - houses[i];
    }
  }

  const dp = Array.from({ length: k + 1 }, () => new Array(n + 1).fill(Infinity));
  dp[0][0] = 0;

  for (let boxes = 1; boxes <= k; boxes++) {
    for (let end = 1; end <= n; end++) {
      for (let start = boxes - 1; start < end; start++) {
        const total = dp[boxes - 1][start] + cost[start][end - 1];
        dp[boxes][end] = Math.min(dp[boxes][end], total);
      }
    }
  }
  return dp[k][n];
}

