function minDistance(houses, k) {
  // Some optimal placement puts every mailbox on a different house, so try every k-subset of houses.
  const n = houses.length;
  let best = Infinity;
  const chosen = [];
  const pick = (from) => {
    if (chosen.length === k) {
      let sum = 0;
      for (const h of houses) sum += Math.min(...chosen.map(c => Math.abs(h - c)));
      best = Math.min(best, sum);
      return;
    }
    for (let i = from; i < n; i++) {
      chosen.push(houses[i]);
      pick(i + 1);
      chosen.pop();
    }
  };
  pick(0);
  return best;
}

