function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 9);
  const top = size === 'large' ? 10000 : (rand() < 0.7 ? 30 : 10000);
  const seen = new Set();
  while (seen.size < n) seen.add(1 + Math.floor(rand() * top));
  const houses = [...seen];
  const k = 1 + Math.floor(rand() * n);
  return [houses, k];
}
